INSERT INTO public.listening_lessons (title, level, description, content) VALUES ('Airport Immigration', 'A1', 'Handling questions and procedures at airport immigration.', '{"part1": {"image_url": "https://images.unsplash.com/photo-1542296332-2e4473faf563?auto=format&fit=crop&q=80&w=800", "options": [{"script": "A scene depicting airport immigration."}, {"script": "A group of people are working in an office."}, {"script": "A traveler is waiting at the station."}], "correct_index": 0}, "part2": [{"question_script": "What is the main topic of airport immigration?", "options": [{"script": "It is about airport immigration."}, {"script": "It''s about cooking."}, {"script": "It''s about the weather."}], "correct_index": 0}, {"question_script": "When do we usually talk about airport immigration?", "options": [{"script": "When it''s raining."}, {"script": "In professional or travel situations."}, {"script": "During the night."}], "correct_index": 1}, {"question_script": "Is airport immigration difficult for you?", "options": [{"script": "Yes, I need to practice."}, {"script": "No, I am sleeping."}, {"script": "Maybe on Monday."}], "correct_index": 0}], "part3": {"dialogue": [{"speaker": "Person A", "text": "Hi! I''m here to learn about airport immigration."}, {"speaker": "Person B", "text": "That''s great! Airport Immigration is a very important part of our course."}, {"speaker": "Person A", "text": "Can you give me an example?"}, {"speaker": "Person B", "text": "Sure, when you are in handling questions and procedures at airport immigration., you use specific vocabulary."}], "questions": [{"enunciado": "What is Person A interested in?", "options": ["Airport Immigration", "A different subject", "Nothing"], "correct_index": 0}, {"enunciado": "How does Person B describe this topic?", "options": ["Boring", "Important", "Unnecessary"], "correct_index": 1}, {"enunciado": "What will Person B provide?", "options": ["An example", "A gift", "A ticket"], "correct_index": 0}]}, "part4": {"script": "This lesson covered airport immigration. We discussed handling questions and procedures at airport immigration. Understanding these concepts is crucial for effective communication in English. Make sure to review the key phrases and use them in your daily life.", "questions": [{"enunciado": "What was the focus of this lesson?", "options": ["Sports", "Airport Immigration", "Movies"], "correct_index": 1}, {"enunciado": "Why is this understanding crucial?", "options": ["For communication", "For sleeping", "For eating"], "correct_index": 0}, {"enunciado": "What is the final advice?", "options": ["Review key phrases", "Forget everything", "Go to sleep"], "correct_index": 0}]}}');
